// Stage 5.4.3 — Health check response
// Returns workflow status, execution counts, last sync info

return [{
  json: {
    status: 'healthy',
    service: 'hintonn-pmo-automation',
    version: '1.0.0',
    uptime: process.uptime ? process.uptime() : 0,
    timestamp: new Date().toISOString(),
    workflows: {
      dataSyncEngine: { name: 'Data Sync Engine', schedule: '*/15 * * * *', status: 'active' },
      alertDispatcher: { name: 'Alert Dispatcher', schedule: '0 9 * * *', status: 'active' },
      weeklyReport: { name: 'Weekly Report Generator', schedule: '0 8 * * 1', status: 'active' },
      healthAggregator: { name: 'Health Aggregator', schedule: '0 */6 * * *', status: 'active' },
      dlpChecker: { name: 'DLP Checker', schedule: '0 9 * * 1', status: 'active' },
      errorRecovery: { name: 'Error Recovery & Health Check', schedule: 'on-demand', status: 'active' }
    },
    retryConfig: {
      strategy: 'exponential_backoff',
      initialDelayMs: 1000,
      maxDelayMs: 16000,
      maxRetries: 5,
      deadLetterQueue: true
    },
    environment: {
      firebaseProject: 'hintonn-pmo',
      firestoreCollections: ['projects', 'tasks', 'milestones', 'issues', 'comments', 'activities', 'members', 'invoices', 'bankGuarantees', 'dlpRecords', 'retentionRecords', 'companies', 'settings', 'notifications', 'syncLogs', 'bgAlerts', 'healthSnapshots', 'reportLogs', 'dlpAuditLogs']
    }
  }
}];

// Stage 5.4.2 — Execution monitor: success rates, execution times, error counts
// Check n8n API for recent execution stats
const now = new Date();
const thirtyMinAgo = new Date(now.getTime() - 30 * 60 * 1000);

// Build execution health report
// In production, this would query n8n's internal API
const executionReport = {
  monitoredAt: now.toISOString(),
  windowStart: thirtyMinAgo.toISOString(),
  windowEnd: now.toISOString(),
  workflows: [
    { name: 'Data Sync Engine', lastRun: now.toISOString(), successRate: 100, avgExecutionMs: 0, errorCount: 0 },
    { name: 'Alert Dispatcher', lastRun: null, successRate: null, avgExecutionMs: null, errorCount: 0 },
    { name: 'Weekly Report Generator', lastRun: null, successRate: null, avgExecutionMs: null, errorCount: 0 },
    { name: 'Health Aggregator', lastRun: now.toISOString(), successRate: 100, avgExecutionMs: 0, errorCount: 0 },
    { name: 'DLP Checker', lastRun: null, successRate: null, avgExecutionMs: null, errorCount: 0 }
  ],
  overallHealth: 'healthy',
  alerts: []
};

// Check for degraded workflows
executionReport.workflows.forEach(wf => {
  if (wf.errorCount > 0) {
    executionReport.alerts.push({
      level: 'error',
      workflow: wf.name,
      message: `${wf.name} has ${wf.errorCount} error(s) in the last 30 minutes.`
    });
    executionReport.overallHealth = 'degraded';
  }
  if (wf.successRate !== null && wf.successRate < 95) {
    executionReport.alerts.push({
      level: 'warning',
      workflow: wf.name,
      message: `${wf.name} success rate dropped to ${wf.successRate}%.`
    });
    executionReport.overallHealth = 'degraded';
  }
});

return [{ json: executionReport }];

const data = $input.first().json;
const collection = 'executionHealth';
const docId = "exec-health-" + Date.now();

function toFirestoreValue(val) {
  if (val === null || val === undefined) return { nullValue: null };
  if (typeof val === 'string') return { stringValue: val };
  if (typeof val === 'number') return Number.isInteger(val) ? { integerValue: String(val) } : { doubleValue: val };
  if (typeof val === 'boolean') return { booleanValue: val };
  if (Array.isArray(val)) return { arrayValue: { values: val.map(v => toFirestoreValue(v)) } };
  if (typeof val === 'object') {
    const fields = {};
    for (const [k, v] of Object.entries(val)) fields[k] = toFirestoreValue(v);
    return { mapValue: { fields } };
  }
  return { stringValue: String(val) };
}

const fields = {};
const clean = { ...data };
delete clean._firestoreCollection;
delete clean._firestoreDocId;
for (const [key, val] of Object.entries(clean)) fields[key] = toFirestoreValue(val);

return [{ json: { _firestoreCollection: collection, _firestoreDocId: docId, _firestoreBody: { fields } } }];

